Before we factorize $20 !$, we need to account for the powers of primes up to $19$. The prime factorization of $20 !$ involves every prime less than $20$ with a power equal to the largest integer $k$ such that $p^k \leq 20$. Specifically:
```python
import sympy

# Function to compute the prime factorization of n!
def factorial_prime_factors(n):
    primes_factors = {}
    for prime in sympy.primerange(2, n+1):
        exponent = 0
        k = prime
        while k <= n:
            exponent += n // k
            k *= prime
        primes_factors[prime] = exponent
    return primes_factors

# Factorization of 20!
prime_factors_of_fact_20 = factorial_prime_factors(20)

# Factorization of 200,000
prime_factors_of_200000 = {2: 5, 5: 5}

# Combine the prime factors of both numbers and take the minimum exponent for each prime
final_factors = {}
for prime in set(prime_factors_of_fact_20.keys()).union(set(prime_factors_of_200000.keys())):
    if prime in prime_factors_of_fact_20:
        exponent_in_fact_20 = prime_factors_of_fact_20[prime]
    else:
        exponent_in_fact_20 = 0

    if prime in prime_factors_of_200000:
        exponent_in_200000 = prime_factors_of_200000[prime]
    else:
        exponent_in_200000 = 0

    if exponent_in_fact_20 >= exponent_in_200000:
        final_factors[prime] = exponent_in_fact_20
    else:
        final_factors[prime] = exponent_in_200000

final_factors = sorted(final_factors.items(), reverse=True)

# Calculate the greatest common factor by multiplying the primes raised to their respective powers
greatest_common_factor = 1
for prime, exponent in final_factors:
    greatest_common_factor *= prime ** exponent

